def step(context):
    world = context['inputs']['observations'][0]['payload']
    decisions = []
    for conference in world['conferences']['conferences']:
        for paper in conference['submitted_papers']:
            reviews = conference['reviews'].get(paper['id'], [])
            actual_mean = sum(r['overall_score'] for r in reviews) / len(reviews) if reviews else 0.0
            decisions.append({'payload':dict(paper_id=paper['id'], conference_id=conference['conference_id'],
                decision='accept', final_score=actual_mean)})
    return dict(outputs={'decisions':decisions or [{'payload':{'empty_cycle':True}}],
        'next':[{'payload':{'year':context['period']}}], 'world':[{'payload':world}]}, state={})

