import hashlib, json
def step(context):
    batch = context['inputs']['batch'][0]['payload']
    coverage = context['parameters']['coverage']
    review_count = context['parameters']['review_count']
    tasks = []
    for paper in batch['papers']:
        # Fixed identity hashing is a reproducible allocation lottery, not a merit estimate.
        key = json.dumps([context['period'], paper['conference_id'], paper['paper_id']], separators=(',', ':'))
        quantile = int(hashlib.sha256(key.encode()).hexdigest()[:13], 16) / float(16 ** 13)
        if quantile >= coverage:
            continue
        eligible = sorted(paper['eligible_reviewer_ids'], key=lambda reviewer:
            hashlib.sha256((key + ':' + reviewer).encode()).hexdigest())
        for reviewer in eligible[:review_count]:
            tasks.append({'conference_id': paper['conference_id'], 'paper_id': paper['paper_id'],
                          'reviewer_id': reviewer})
    command = {'schema': 'native-review-routing-plan-v13', 'year': context['period'],
        'batch_sha256': hashlib.sha256(json.dumps(batch, sort_keys=True, separators=(',', ':'),
            ensure_ascii=False, allow_nan=False).encode('utf-8')).hexdigest(), 'tasks': tasks}
    return {'outputs': {'routing': [{'payload': command}]},
            'state': {'cycles': context['state'].get('cycles', 0) + 1, 'last_tasks': len(tasks)}}

